<?php
require_once __DIR__ . "/auth.php";

$from = $_GET['from'] ?? date('Y-m-01');
$to = $_GET['to'] ?? date('Y-m-d');
if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $from)) $from = date('Y-m-01');
if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $to)) $to = date('Y-m-d');

$stmt = $conn->prepare("SELECT attendance_date,time_in,time_out,total_hours,ot_hours,status,remarks FROM attendance WHERE employee_id=? AND attendance_date BETWEEN ? AND ? ORDER BY attendance_date DESC");
$stmt->bind_param("iss", $employeeId, $from, $to);
$stmt->execute();
$rows = $stmt->get_result();

$sumStmt = $conn->prepare("SELECT COALESCE(SUM(total_hours),0) total_hours, COALESCE(SUM(ot_hours),0) ot_hours, COUNT(CASE WHEN status IN ('Present','Late','Half Day') THEN 1 END) days_present, COUNT(CASE WHEN status='Late' THEN 1 END) late_days, COUNT(CASE WHEN status='Absent' THEN 1 END) absent_days, COUNT(CASE WHEN status='On Leave' THEN 1 END) leave_days FROM attendance WHERE employee_id=? AND attendance_date BETWEEN ? AND ?");
$sumStmt->bind_param("iss", $employeeId, $from, $to);
$sumStmt->execute();
$summary = $sumStmt->get_result()->fetch_assoc();
?>
